package in.suniye.app;
import android.app.Activity;
import android.app.AlertDialog;
import android.content.Intent;
import android.os.Bundle;
import android.provider.Settings;
import android.text.InputType;
import android.widget.*;
public final class SetupActivity extends Activity {
    private Config config;private ReaderController reader;private final java.util.concurrent.ExecutorService syncWorker=java.util.concurrent.Executors.newSingleThreadExecutor();
    @Override public void onCreate(Bundle b){super.onCreate(b);config=new Config(this);reader=SuniyeApp.reader(this);Button stop=Ui.button(this,"रोकिए",true);stop.setOnClickListener(v->reader.stop());LinearLayout root=Ui.screenWithControls(this,stop);Ui.add(root,Ui.text(this,"परिवार की सेटिंग",28,Ui.INK,true),-2,0);Ui.add(root,Ui.text(this,"यह सेटिंग परिवार का सदस्य एक बार करे।",18,Ui.MUTED,false),-2,8);
        Ui.add(root,Ui.text(this,"चित्र का पाठ इस फ़ोन पर पहचानेंगे। सुनने के लिए पाठ आपके चुने सर्वर और ElevenLabs तक जाएगा। हिंदी आवाज़ Raju की है। नया पाठ सुनने के लिए इंटरनेट चाहिए। सहेजी हुई आवाज़ फिर बिना इंटरनेट सुन सकते हैं। चित्र का वर्णन या समझाइए चुनें तो सामग्री AI तक भी जाएगी। बैंक की सुरक्षित स्क्रीन नहीं पढ़ेंगे।",23,Ui.INK,false),-2,20);
        CheckBox consent=new CheckBox(this);consent.setText("मुझे समझाया गया है और मैं सहमत हूँ");consent.setTextSize(24);consent.setMinHeight(Ui.dp(this,64));consent.setTextColor(Ui.INK);consent.setChecked(config.acknowledged());Ui.add(root,consent,-2,16);
        EditText endpoint=field(root,"Backend HTTPS address",config.endpoint(),false);EditText token=field(root,"Family access token (32+ characters)","",true);EditText profile=field(root,"Profile: mother / father",config.profile(),false);
        Button save=Ui.button(this,"सेटिंग सहेजें",true);save.setOnClickListener(v->{try{if(!consent.isChecked())throw new UserMessage("पहले ऊपर सहमति चुनें।");String value=token.getText().toString();if(value.isEmpty())value=config.token();config.save(endpoint.getText().toString(),value,profile.getText().toString());config.acknowledge();config.setOnlineVoice(true);reader.announce("सेटिंग सहेज दी। अब हिंदी आवाज़ और स्क्रीन पढ़ने की अनुमति जाँचें।");Toast.makeText(this,"सेटिंग सहेज दी",Toast.LENGTH_LONG).show();}catch(Exception e){new AlertDialog.Builder(this).setMessage(UserMessage.display(e,"सेटिंग नहीं सहेज पाए। परिवार के सदस्य से मदद लें।")).setPositiveButton("ठीक है",null).show();}});Ui.add(root,save,-2,20);
        Ui.add(root,Ui.text(this,"सुनिए में केवल ElevenLabs की हिंदी आवाज़ बजेगी। सेवा न मिले तो मूल पाठ दिखेगा; कोई दूसरी आवाज़ नहीं बजेगी।",22,Ui.MUTED,false),-2,20);
        Ui.add(root,Ui.text(this,"बोलिए बटन दबाकर ऐप चलाएँ। माइक केवल उस छोटे सत्र में सुनता है। जहाँ उपलब्ध हो, फ़ोन पर आवाज़ पहचानेंगे; दूसरी फ़ोन सेवा आपकी आवाज़ इंटरनेट पर भेज सकती है।",23,Ui.INK,false),-2,20);
        CheckBox commands=new CheckBox(this);commands.setText("बोलकर चलाना चालू करें (माइक की पहचान सेवा)");commands.setTextSize(24);commands.setTextColor(Ui.INK);commands.setMinHeight(Ui.dp(this,64));commands.setChecked(config.voiceCommandsEnabled());commands.setOnCheckedChangeListener((control,checked)->{if(checked&&!config.acknowledged()){commands.setChecked(false);reader.announce("पहले सहमति समझाकर सेटिंग सहेजें।");return;}config.setVoiceCommandsEnabled(checked);});Ui.add(root,commands,-2,12);
        if(android.os.Build.MANUFACTURER.toLowerCase(java.util.Locale.ROOT).matches(".*(xiaomi|redmi).*")){Ui.add(root,Ui.text(this,"Redmi A4: फ़ोन की सेटिंग में Background autostart खोजें और सुनिए की सेटिंग जाँचें। अनुमति और हिंदी आवाज़ जाँचने के बाद फ़ोन लॉक करके WhatsApp में दोबारा परीक्षण करें।",22,Ui.MUTED,false),-2,20);Button info=Ui.button(this,"फ़ोन की ऐप सेटिंग",false);info.setTextSize(23);info.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,android.net.Uri.parse("package:"+getPackageName()))));Ui.add(root,info,-2,12);}
        Button voice=Ui.button(this,"हिंदी आवाज़ जाँचें",false);voice.setOnClickListener(v->reader.readText("नमस्ते। मैं आपके लिए हिंदी में पढ़ूँगा।"));Ui.add(root,voice,-2,16);
        Ui.add(root,Ui.text(this,"आवाज़ बंद हो तो फ़ोन का आवाज़ बढ़ाने वाला बटन दबाएँ। आवाज़ न मिले तो इंटरनेट और ऊपर की सर्वर सेटिंग जाँचें।",22,Ui.MUTED,false),-2,16);
        Button access=Ui.button(this,"स्क्रीन पढ़ने की अनुमति",false);access.setTextSize(24);access.setOnClickListener(v->{if(!config.acknowledged()){reader.announce("पहले सहमति चुनकर सेटिंग सहेजें।");return;}startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS));});Ui.add(root,access,-2,16);
        Button side=Ui.button(this,"बटन की जगह: "+(config.placement().equals("left")?"बाएँ":"दाएँ"),false);side.setTextSize(24);side.setOnClickListener(v->{config.setPlacement(config.placement().equals("left")?"right":"left");side.setText("बटन की जगह: "+(config.placement().equals("left")?"बाएँ":"दाएँ"));});Ui.add(root,side,-2,16);
        Ui.add(root,Ui.text(this,"वैकल्पिक: परिवार की दूसरी डिवाइस से आवाज़ की गति और बटन की जगह मिलाएँ। चित्र और पढ़ा हुआ पाठ नहीं भेजेंगे।",22,Ui.MUTED,false),-2,24);
        Button push=Ui.button(this,"इस फ़ोन की सेटिंग सहेजें",false);push.setTextSize(23);push.setOnClickListener(v->sync(true,push));Ui.add(root,push,-2,12);
        Button pull=Ui.button(this,"सहेजी हुई सेटिंग लाएँ",false);pull.setTextSize(23);pull.setOnClickListener(v->sync(false,pull));Ui.add(root,pull,-2,12);
        Button delete=Ui.button(this,"पिछला पढ़ना मिटाएँ",false);delete.setTextSize(24);delete.setOnClickListener(v->new AlertDialog.Builder(this).setMessage("इस फ़ोन का पिछला पढ़ना मिटाएँ?").setNegativeButton("रहने दें",null).setPositiveButton("मिटाएँ",(d,w)->reader.forget()).show());Ui.add(root,delete,-2,20);
    }
    private void sync(boolean upload,Button button){button.setEnabled(false);syncWorker.submit(()->{String message;try{org.json.JSONObject response=PreferencesClient.sync(config,upload);if(!upload)PreferencesClient.apply(config,response);message=upload?"परिवार की सेटिंग सहेज दी।":"परिवार की सेटिंग मिल गई।";}catch(Exception e){message=UserMessage.display(e,"सेटिंग इस फ़ोन पर सुरक्षित है। इंटरनेट और सर्वर की सेटिंग जाँचें।");}String result=message;runOnUiThread(()->{if(isFinishing()||isDestroyed())return;button.setEnabled(true);new AlertDialog.Builder(this).setMessage(result).setPositiveButton("ठीक है",null).show();});});}
    @Override protected void onDestroy(){syncWorker.shutdownNow();super.onDestroy();}
    private EditText field(LinearLayout root,String title,String value,boolean secret){Ui.add(root,Ui.text(this,title,20,Ui.MUTED,true),-2,20);EditText edit=new EditText(this);edit.setText(value);edit.setTextSize(22);edit.setTextColor(Ui.INK);edit.setSingleLine(true);edit.setInputType(InputType.TYPE_CLASS_TEXT|(secret?InputType.TYPE_TEXT_VARIATION_PASSWORD:InputType.TYPE_TEXT_VARIATION_URI));edit.setImportantForAutofill(android.view.View.IMPORTANT_FOR_AUTOFILL_NO);edit.setContentDescription(title);edit.setMinHeight(Ui.dp(this,64));Ui.add(root,edit,-2,8);return edit;}
}
